 *  - Retry of idempotent requests (GET/HEAD/OPTIONS) once on upstream 502/503
 *  - Upstream timeout (default 2s) answered with 504
 *  - X-Forwarded-For appending + X-Request-ID propagation/generation
 */

const http = require('node:http');
const crypto = require('node:crypto');
const fs = require('node:fs');

// ---------------------------------------------------------------------------
// Token bucket
// ---------------------------------------------------------------------------

class TokenBucket {
  constructor(capacity, refillPerSecond) {
    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.tokens = capacity;
    this.lastRefill = Date.now();
  }

  refill() {
    const now = Date.now();
    if (now <= this.lastRefill) return;
    const elapsedSeconds = (now - this.lastRefill) / 1000;
    this.tokens = Math.min(
      this.capacity,
      this.tokens + elapsedSeconds * this.refillPerSecond
    );
    this.lastRefill = now;
  }

  take() {
    this.refill();
    if (this.tokens >= 1) {
      this.tokens -= 1;
      return true;
    }
    return false;
  }
}

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------

function parseArgs(argv) {
  const args = { port: process.env.PORT || 8080, routes: 'routes.json' };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--port') args.port = Number(argv[++i]);
    else if (argv[i] === '--routes') args.routes = argv[++i];
  }
  return args;
}

function loadConfig(file) {
  const raw = JSON.parse(fs.readFileSync(file, 'utf8'));
  const retry = {
    methods: new Set((raw.retry && raw.retry.methods) || ['GET']),
    statuses: new Set((raw.retry && raw.retry.statuses) || [502, 503]),
    maxRetries: (raw.retry && raw.retry.maxRetries) || 1,
  };
  // Longest prefix first so /api/users/x wins over /api/users.
  const routes = [...raw.routes]
    .sort((a, b) => b.prefix.length - a.prefix.length)
    .map((r) => ({
      prefix: r.prefix,
      rewrite: r.rewrite || '',
      upstreamEnv: r.upstreamEnv,
      rateLimit: r.rateLimit || null,
      bucket: r.rateLimit
        ? new TokenBucket(r.rateLimit.capacity, r.rateLimit.refillPerSecond)
        : null,
    }));
  return { timeoutMs: raw.timeoutMs || 2000, retry, routes };
}

function matchRoute(routes, pathname) {
  for (const route of routes) {
    if (
      pathname === route.prefix ||
      pathname.startsWith(route.prefix + '/')
    ) {
      return route;
    }
  }
  return null;
}

function rewritePath(route, pathname) {
  if (pathname === route.prefix) return route.rewrite || '/';
  return route.rewrite + pathname.slice(route.prefix.length);
}

// ---------------------------------------------------------------------------
// Proxy plumbing
// ---------------------------------------------------------------------------

const HOP_BY_HOP = new Set([
  'connection',
  'keep-alive',
  'proxy-authenticate',
  'proxy-authorization',
  'te',
  'trailers',
  'transfer-encoding',
  'upgrade',
]);

function readBody(req) {
  return new Promise((resolve) => {
    const chunks = [];
    req.on('data', (c) => chunks.push(c));
    req.on('end', () => resolve(Buffer.concat(chunks)));
    req.on('error', () => resolve(Buffer.alloc(0)));
  });
}

function buildUpstreamHeaders(req, body, requestId) {
  const headers = {};
  for (const [key, value] of Object.entries(req.headers)) {
    if (!HOP_BY_HOP.has(key)) headers[key] = value;
  }
  const ip = req.socket.remoteAddress || 'unknown';
  const incomingXff = req.headers['x-forwarded-for'];
  headers['x-forwarded-for'] = incomingXff
    ? `${incomingXff}, ${ip}`
    : ip;
  headers['x-request-id'] = requestId;
  delete headers.host;
  delete headers['content-length'];
  if (body.length > 0) headers['content-length'] = String(body.length);
  return headers;
}

/**
 * Single attempt against an upstream. Calls cb(err, upstreamResponse).
 * err.code === 'GATEWAY_TIMEOUT' marks a timeout (=> 504, never retried).
 */
function attempt(upstreamUrl, options, body, timeoutMs, cb) {
  const url = new URL(upstreamUrl);
  const req = http.request(
    {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname + url.search,
      method: options.method,
      headers: options.headers,
    },
    (res) => cb(null, res)
  );
  let timedOut = false;
  req.setTimeout(timeoutMs, () => {
    timedOut = true;
    const err = new Error(`upstream timeout after ${timeoutMs}ms`);
    err.code = 'GATEWAY_TIMEOUT';
    req.destroy(err);
  });
  req.on('error', (err) => {
    if (!timedOut) cb(err);
    else cb(err); // still call cb once; destroy triggers 'error' exactly once
  });
  if (body.length > 0) req.write(body);
  req.end();
}

function sendError(res, status, code, message, requestId) {
  if (res.headersSent) return res.destroy();
  res.writeHead(status, {
    'content-type': 'application/json',
    'x-request-id': requestId,
  });
  res.end(JSON.stringify({ error: code, message }));
}

// ---------------------------------------------------------------------------
// Gateway server
// ---------------------------------------------------------------------------

function createGateway(config) {
  return http.createServer(async (req, res) => {
    const requestId =
      req.headers['x-request-id'] || crypto.randomUUID();
    const url = new URL(req.url, 'http://gateway.local');
    const route = matchRoute(config.routes, url.pathname);

    if (!route) {
      return sendError(
        res,
        404,
        'NO_ROUTE',
        `no route matches ${url.pathname}`,
        requestId
      );
    }

    if (route.bucket && !route.bucket.take()) {
      res.writeHead(429, {
        'content-type': 'application/json',
        'x-request-id': requestId,
        'retry-after': '1',
      });
      return res.end(JSON.stringify({ error: 'RATE_LIMITED' }));
    }

    const upstreamBase = process.env[route.upstreamEnv];
    if (!upstreamBase) {
      return sendError(
        res,
        502,
        'BAD_CONFIG',
        `upstream env ${route.upstreamEnv} is not set`,
        requestId
      );
    }

    const target =
      upstreamBase.replace(/\/$/, '') +
      rewritePath(route, url.pathname) +
      url.search;

    const body = await readBody(req);
    const headers = buildUpstreamHeaders(req, body, requestId);
    const canRetry =
      config.retry.methods.has(req.method) &&
      config.retry.maxRetries > 0;

    const tryOnce = (attemptNo) => {
      attempt(target, { method: req.method, headers }, body, config.timeoutMs, (err, upRes) => {
        if (err) {
          if (err.code === 'GATEWAY_TIMEOUT') {
            return sendError(res, 504, 'UPSTREAM_TIMEOUT', `upstream did not respond within ${config.timeoutMs}ms`, requestId);
          }
          // Connection-level failure: retry idempotent methods too.
          if (canRetry && attemptNo < config.retry.maxRetries) {
            return tryOnce(attemptNo + 1);
          }
          return sendError(res, 502, 'BAD_GATEWAY', `upstream unreachable: ${err.message}`, requestId);
        }

        const retryableStatus = config.retry.statuses.has(upRes.statusCode);
        if (retryableStatus && canRetry && attemptNo < config.retry.maxRetries) {
          upRes.resume(); // drain and discard the failed attempt
          return tryOnce(attemptNo + 1);
        }

        const responseHeaders = {};
        for (const [key, value] of Object.entries(upRes.headers)) {
          if (!HOP_BY_HOP.has(key)) responseHeaders[key] = value;
        }
        responseHeaders['x-request-id'] = requestId;
        res.writeHead(upRes.statusCode, responseHeaders);
        upRes.pipe(res);
      });
    };

    tryOnce(0);
  });
}

// ---------------------------------------------------------------------------

if (require.main === module) {
  const args = parseArgs(process.argv.slice(2));
  const config = loadConfig(args.routes);
  const server = createGateway(config);
  server.listen(args.port, '127.0.0.1', () => {
    const port = server.address().port;
    console.log(`READY ${port}`);
  });
}

module.exports = { createGateway, loadConfig, matchRoute, rewritePath, TokenBucket };
"})
