#!/usr/bin/env node
'use strict';

/**
 * orders-svc: tiny Express backend with invocation counters so the
 * integration suite can prove that GETs are retried once on 502/503
 * while POSTs are never retried.
 */

const express = require('express');
const crypto = require('node:crypto');

function createApp() {
  const app = express();
  const state = { flaky: 0, broken: 0, orders: 0 };

  const echo = (req, res) => {
    res.json({
      service: 'orders',
      method: req.method,
      path: req.originalUrl.split('?')[0],
      headers: {
        'x-request-id': req.headers['x-request-id'] || null,
        'x-forwarded-for': req.headers['x-forwarded-for'] || null,
      },
    });
  };

  app.get('/orders/_stats', (req, res) => res.json(state));
  app.post('/orders/_reset', (req, res) => {
    state.flaky = 0;
    state.broken = 0;
    state.orders = 0;
    res.json({ reset: true });
  });

  // Fails with 503 on first hit, succeeds afterwards.
  app.all('/orders/flaky', (req, res) => {
    state.flaky += 1;
    if (state.flaky === 1) return res.status(503).json({ error: 'flaky' });
    res.json({
      service: 'orders',
      ok: true,
      attempts: state.flaky,
      idempotencyKey: crypto.randomUUID(),
    });
  });

  // Always 502.
  app.all('/orders/broken', (req, res) => {
    state.broken += 1;
    res.status(502).json({ error: 'broken' });
  });

  app.post('/orders', (req, res) => {
    state.orders += 1;
    res.status(201).json({
      service: 'orders',
      created: true,
      headers: {
        'x-request-id': req.headers['x-request-id'] || null,
        'x-forwarded-for': req.headers['x-forwarded-for'] || null,
      },
    });
  });

  app.all('/orders', echo);
  app.all('/orders/*', echo);

  return app;
}

if (require.main === module) {
  const app = createApp();
  const server = app.listen(Number(process.env.PORT || 0), '127.0.0.1', () => {
    console.log(`READY ${server.address().port}`);
  });
}

module.exports = { createApp };

