'use strict';

/**
 * Integration tests: boot gateway + users-svc + orders-svc as three real
 * child processes on random ports, then exercise every gateway feature
 * over HTTP.
 */

const { describe, it, before, after } = require('node:test');
const assert = require('node:assert/strict');
const { spawn } = require('node:child_process');
const path = require('node:path');

const ROOT = path.join(__dirname, '..');
const GATEWAY = path.join(ROOT, 'src', 'gateway.js');
const USERS = path.join(ROOT, 'src', 'services', 'users-svc.js');
const ORDERS = path.join(ROOT, 'src', 'services', 'orders-svc.js');

function spawnReady(nodeArgs, env = {}) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, nodeArgs, {
      cwd: ROOT,
      env: { ...process.env, ...env },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let stdout = '';
    let stderr = '';
    const timer = setTimeout(
      () => reject(new Error(`process did not become ready: ${nodeArgs.join(' ')}\n${stderr}`)),
      10000
    );
    child.stdout.on('data', (d) => {
      stdout += d.toString();
      const match = stdout.match(/^READY (\d+)/m);
      if (match) {
        clearTimeout(timer);
        resolve({ child, port: Number(match[1]) });
      }
    });
    child.stderr.on('data', (d) => (stderr += d.toString()));
    child.on('exit', (code) => {
      clearTimeout(timer);
      if (code !== 0 && code !== null) {
        reject(new Error(`process exited ${code}: ${nodeArgs.join(' ')}\n${stderr}`));
      }
    });
  });
}

describe('mini api gateway', async () => {
  const procs = {};
  let gw; // http://127.0.0.1:<gatewayPort>

  before(async () => {
    const users = await spawnReady([USERS]);
    const orders = await spawnReady([ORDERS]);
    const gateway = await spawnReady([GATEWAY, '--port', '0', '--routes', 'routes.json'], {
      USERS_SVC: `http://127.0.0.1:${users.port}`,
      ORDERS_SVC: `http://127.0.0.1:${orders.port}`,
    });
    Object.assign(procs, { users, orders, gateway });
    gw = `http://127.0.0.1:${gateway.port}`;
  });

  after(async () => {
    await Promise.all(
      Object.values(procs).map(
        (p) =>
          p &&
          new Promise((resolve) => {
            p.child.kill('SIGTERM');
            p.child.on('exit', resolve);
          })
      )
    );
  });

  const resetOrders = () => fetch(`${gw}/api/orders/_reset`, { method: 'POST' });
  const stats = async () => (await fetch(`${gw}/api/orders/_stats`)).json();

  describe('prefix routing with path rewrite', () => {
    it('routes /api/users/* to users-svc and rewrites to /users/*', async () => {
      const res = await fetch(`${gw}/api/users/42?full=1`);
      assert.equal(res.status, 200);
      const body = await res.json();
      assert.equal(body.service, 'users');
      assert.equal(body.path, '/users/42');
      assert.equal(body.query.full, '1');
    });

    it('routes /api/orders/* to orders-svc and rewrites to /orders/*', async () => {
      const res = await fetch(`${gw}/api/orders/7`);
      assert.equal(res.status, 200);
      const body = await res.json();
      assert.equal(body.service, 'orders');
      assert.equal(body.path, '/orders/7');
    });

    it('rewrites the bare prefix itself (/api/users -> /users)', async () => {
      const res = await fetch(`${gw}/api/users`);
      assert.equal(res.status, 200);
      assert.equal((await res.json()).path, '/users');
    });

    it('returns 404 for unknown prefixes', async () => {
      const res = await fetch(`${gw}/api/nope`);
      assert.equal(res.status, 404);
      assert.equal((await res.json()).error, 'NO_ROUTE');
    });
  });

  describe('X-Forwarded-For and X-Request-ID propagation', () => {
    it('propagates an incoming X-Request-ID to the backend', async () => {
      const res = await fetch(`${gw}/api/users/1`, {
        headers: { 'x-request-id': 'test-rid-123' },
      });
      const body = await res.json();
      assert.equal(res.headers.get('x-request-id'), 'test-rid-123');
      assert.equal(body.headers['x-request-id'], 'test-rid-123');
    });

    it('generates an X-Request-ID when none is supplied and echoes it back', async () => {
      const res = await fetch(`${gw}/api/orders/5`);
      const rid = res.headers.get('x-request-id');
      assert.ok(rid && rid.length >= 32, `expected a generated id, got ${rid}`);
      assert.equal((await res.json()).headers['x-request-id'], rid);
    });

    it('appends the client IP to an incoming X-Forwarded-For chain', async () => {
      const res = await fetch(`${gw}/api/users/2`, {
        headers: { 'x-forwarded-for': '10.0.0.1' },
      });
      const body = await res.json();
      assert.equal(body.headers['x-forwarded-for'], '10.0.0.1, 127.0.0.1');
    });

    it('sets X-Forwarded-For from the socket address when absent', async () => {
      const body = await (await fetch(`${gw}/api/orders/3`)).json();
      assert.equal(body.headers['x-forwarded-for'], '127.0.0.1');
    });
  });

  describe('per-route token-bucket rate limits', () => {
    it('allows bursts up to capacity then returns 429, refilling over time', async () => {
      // /api/limited has capacity 3, refillPerSecond 1.
      const statuses = [];
      for (let i = 0; i < 4; i++) {
        statuses.push((await fetch(`${gw}/api/limited/ping`)).status);
      }
      assert.deepEqual(statuses, [200, 200, 200, 429]);

      // Wait for ~2 tokens to refill, next request must pass again.
      await new Promise((r) => setTimeout(r, 1500));
      const after = await fetch(`${gw}/api/limited/ping`);
      assert.equal(after.status, 200);
      assert.equal((await after.json()).path, '/users/ping');
    });

    it('does not throttle other routes when one route is exhausted', async () => {
      // /api/limited is drained from the previous test; /api/users is not.
      const res = await fetch(`${gw}/api/users/rate-check`);
      assert.equal(res.status, 200);
    });
  });

  describe('retry of idempotent GETs on 502/503', () => {
    it('retries a GET once on 503 and succeeds on the second attempt', async () => {
      await resetOrders();
      const res = await fetch(`${gw}/api/orders/flaky`);
      assert.equal(res.status, 200);
      const body = await res.json();
      assert.equal(body.attempts, 2); // first attempt failed, retry succeeded

      const s = await stats();
      assert.equal(s.flaky, 2);
    });

    it('retries at most once when upstream keeps returning 503', async () => {
      await resetOrders();
      // First request burns the flaky counter's success; make every hit fail by
      // using /broken which always 502s.
      const res = await fetch(`${gw}/api/orders/broken`);
      assert.equal(res.status, 502);

      const s = await stats();
      assert.equal(s.broken, 2); // exactly one retry, no more
    });

    it('never retries a POST even when it gets a 503', async () => {
      await resetOrders();
      const res = await fetch(`${gw}/api/orders/flaky`, { method: 'POST' });
      assert.equal(res.status, 503); // flaky fails its first invocation

      const s = await stats();
      assert.equal(s.flaky, 1); // exactly ONE invocation => no retry
    });

    it('does not retry a POST that succeeds', async () => {
      await resetOrders();
      const res = await fetch(`${gw}/api/orders`, {
        method: 'POST',
        headers: { 'content-type': 'application/json', 'x-request-id': 'post-rid-1' },
        body: JSON.stringify({ item: 'widget' }),
      });
      assert.equal(res.status, 201);
      const body = await res.json();
      assert.equal(body.created, true);
      assert.equal(body.headers['x-request-id'], 'post-rid-1');

      const s = await stats();
      assert.equal(s.orders, 1);
    });
  });

  describe('upstream timeout', () => {
    it('returns 504 within about 2s when the upstream hangs', async () => {
      const start = Date.now();
      const res = await fetch(`${gw}/api/users/slow`); // backend sleeps 3s
      const elapsed = Date.now() - start;
      assert.equal(res.status, 504);
      assert.ok(elapsed >= 1800 && elapsed < 3500, `expected ~2s, took ${elapsed}ms`);
      const body = await res.json();
      assert.equal(body.error, 'UPSTREAM_TIMEOUT');
    });
  });
});

